[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>ScreenVault — UI & UX design inspiration for mobile & web apps</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    :root {
      --brand-primary: oklch(55% 0.22 265);
      --brand-accent: oklch(60% 0.25 270);
      --text-primary: oklch(12% 0.02 265);
      --text-secondary: oklch(45% 0.02 265);
      --text-muted: oklch(55% 0.02 265);
      --bg-white: oklch(99% 0.01 265);
      --bg-surface: oklch(98% 0.01 265);
      --bg-card: oklch(99% 0.01 265);
      --border-subtle: oklch(92% 0.01 265);
      --border-light: oklch(88% 0.01 265);
      --shadow-sm: 0 1px 2px oklch(0% 0 0 / 0.04);
      --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.06);
      --shadow-lg: 0 8px 24px oklch(0% 0 0 / 0.08);
      --shadow-xl: 0 16px 48px oklch(0% 0 0 / 0.1);
      --radius-sm: 6px;
      --radius-md: 10px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --radius-full: 9999px;
      --transition-fast: 150ms ease;
      --transition-base: 200ms ease;
      --transition-slow: 300ms ease;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--bg-white);
      color: var(--text-primary);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* Announcement Bar */
    .announcement-bar {
      background: var(--brand-primary);
      color: white;
      text-align: center;
      padding: 10px 24px;
      font-size: 13px;
      font-weight: 500;
      letter-spacing: 0.01em;
    }

    /* Navigation */
    .nav {
      position: sticky;
      top: 0;
      background: rgba(255, 255, 255, 0.9);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border-subtle);
      z-index: 100;
    }

    .nav-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 16px 24px;
      max-width: 1200px;
      margin: 0 auto;
    }

    .nav-logo {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 18px;
      font-weight: 700;
      color: var(--text-primary);
      text-decoration: none;
    }

    .nav-logo svg {
      width: 28px;
      height: 28px;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .nav-links a {
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      text-decoration: none;
      transition: color var(--transition-fast);
    }

    .nav-links a:hover {
      color: var(--text-primary);
    }

    .nav-cta {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    /* Buttons */
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      padding: 10px 20px;
      font-size: 14px;
      font-weight: 600;
      border-radius: var(--radius-full);
      text-decoration: none;
      cursor: pointer;
      transition: all var(--transition-base);
      border: none;
      gap: 8px;
    }

    .btn-primary {
      background: var(--brand-primary);
      color: white;
    }

    .btn-primary:hover {
      background: oklch(50% 0.22 265);
      transform: translateY(-1px);
      box-shadow: var(--shadow-md);
    }

    .btn-secondary {
      background: transparent;
      color: var(--text-primary);
      border: 1px solid var(--border-light);
    }

    .btn-secondary:hover {
      background: var(--bg-surface);
      border-color: var(--border-light);
    }

    .btn-lg {
      padding: 14px 28px;
      font-size: 15px;
    }

    /* Hero Section */
    .hero {
      padding: 80px 0 100px;
      text-align: center;
      background: var(--bg-white);
    }

    .hero-title {
      font-size: clamp(40px, 6vw, 64px);
      font-weight: 700;
      letter-spacing: -0.03em;
      line-height: 1.1;
      color: var(--text-primary);
      margin-bottom: 20px;
    }

    .hero-subtitle {
      font-size: 18px;
      color: var(--text-secondary);
      max-width: 540px;
      margin: 0 auto 40px;
    }

    .hero-cta {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 16px;
      flex-wrap: wrap;
    }

    /* Trusted By */
    .trusted-by {
      padding: 48px 0;
      border-top: 1px solid var(--border-subtle);
      border-bottom: 1px solid var(--border-subtle);
      background: var(--bg-surface);
    }

    .trusted-by-label {
      text-align: center;
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--text-muted);
      margin-bottom: 24px;
    }

    .logo-row {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 48px;
      flex-wrap: wrap;
      opacity: 0.6;
    }

    .logo-row svg {
      height: 24px;
      width: auto;
    }

    /* Stats Section */
    .stats {
      padding: 80px 0;
      background: var(--bg-white);
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 32px;
      max-width: 800px;
      margin: 0 auto;
    }

    .stat-card {
      text-align: center;
      padding: 32px;
      background: var(--bg-surface);
      border-radius: var(--radius-lg);
      border: 1px solid var(--border-subtle);
    }

    .stat-number {
      font-size: 48px;
      font-weight: 700;
      color: var(--brand-primary);
      line-height: 1;
      margin-bottom: 8px;
      font-variant-numeric: tabular-nums;
    }

    .stat-label {
      font-size: 14px;
      color: var(--text-secondary);
      font-weight: 500;
    }

    /* Features Search Section */
    .features-search {
      padding: 100px 0;
      background: var(--bg-white);
    }

    .section-header {
      text-align: center;
      max-width: 600px;
      margin: 0 auto 48px;
    }

    .section-tag {
      display: inline-block;
      padding: 6px 12px;
      background: var(--bg-surface);
      border-radius: var(--radius-full);
      font-size: 12px;
      font-weight: 600;
      color: var(--brand-primary);
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 16px;
    }

    .section-title {
      font-size: clamp(28px, 4vw, 40px);
      font-weight: 700;
      letter-spacing: -0.02em;
      color: var(--text-primary);
      margin-bottom: 16px;
    }

    .section-desc {
      font-size: 16px;
      color: var(--text-secondary);
    }

    .search-tabs {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      margin-bottom: 32px;
      flex-wrap: wrap;
    }

    .search-tab {
      padding: 10px 20px;
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      background: transparent;
      border: 1px solid var(--border-light);
      border-radius: var(--radius-full);
      cursor: pointer;
      transition: all var(--transition-base);
    }

    .search-tab:hover {
      border-color: var(--brand-primary);
      color: var(--brand-primary);
    }

    .search-tab.active {
      background: var(--brand-primary);
      color: white;
      border-color: var(--brand-primary);
    }

    .filter-pills {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      margin-bottom: 40px;
      flex-wrap: wrap;
      padding: 0 16px;
    }

    .filter-pill {
      padding: 8px 16px;
      font-size: 13px;
      font-weight: 500;
      color: var(--text-secondary);
      background: var(--bg-surface);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-full);
      cursor: pointer;
      transition: all var(--transition-base);
      white-space: nowrap;
    }

    .filter-pill:hover {
      border-color: var(--brand-primary);
      color: var(--brand-primary);
    }

    .filter-pill.active {
      background: var(--brand-primary);
      color: white;
      border-color: var(--brand-primary);
    }

    .screenshots-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
    }

    .screenshot-card {
      aspect-ratio: 9/16;
      background: linear-gradient(135deg, var(--bg-surface) 0%, var(--border-subtle) 100%);
      border-radius: var(--radius-md);
      border: 1px solid var(--border-subtle);
      overflow: hidden;
      transition: all var(--transition-base);
      position: relative;
    }

    .screenshot-card::after {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,0.04) 100%);
    }

    .screenshot-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    /* Features Flows Section */
    .features-flows {
      padding: 100px 0;
      background: var(--bg-surface);
    }

    .flows-toggle {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 4px;
      padding: 4px;
      background: var(--bg-white);
      border-radius: var(--radius-full);
      margin-bottom: 48px;
      width: fit-content;
      margin-left: auto;
      margin-right: auto;
      border: 1px solid var(--border-subtle);
    }

    .flows-toggle-btn {
      padding: 10px 24px;
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      background: transparent;
      border: none;
      border-radius: var(--radius-full);
      cursor: pointer;
      transition: all var(--transition-base);
    }

    .flows-toggle-btn.active {
      background: var(--brand-primary);
      color: white;
    }

    .flows-content {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 24px;
    }

    .flow-card {
      background: var(--bg-white);
      border-radius: var(--radius-lg);
      border: 1px solid var(--border-subtle);
      overflow: hidden;
      padding: 24px;
    }

    .flow-preview {
      aspect-ratio: 16/9;
      background: linear-gradient(135deg, var(--brand-primary) 0%, oklch(45% 0.22 265) 100%);
      border-radius: var(--radius-md);
      margin-bottom: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .flow-preview svg {
      width: 48px;
      height: 48px;
      color: white;
      opacity: 0.8;
    }

    .flow-title {
      font-size: 16px;
      font-weight: 600;
      color: var(--text-primary);
      margin-bottom: 8px;
    }

    .flow-desc {
      font-size: 14px;
      color: var(--text-secondary);
    }

    /* Features Tools Section */
    .features-tools {
      padding: 100px 0;
      background: var(--bg-white);
    }

    .tools-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .tool-card {
      background: var(--bg-surface);
      border-radius: var(--radius-lg);
      border: 1px solid var(--border-subtle);
      padding: 32px;
      transition: all var(--transition-base);
    }

    .tool-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
      border-color: var(--brand-primary);
    }

    .tool-icon {
      width: 48px;
      height: 48px;
      background: var(--brand-primary);
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 20px;
    }

    .tool-icon svg {
      width: 24px;
      height: 24px;
      color: white;
    }

    .tool-title {
      font-size: 18px;
      font-weight: 600;
      color: var(--text-primary);
      margin-bottom: 8px;
    }

    .tool-desc {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.6;
    }

    /* Testimonials Section */
    .testimonials {
      padding: 100px 0;
      background: var(--bg-surface);
      overflow: hidden;
    }

    .testimonials-row {
      display: flex;
      gap: 24px;
      margin-bottom: 24px;
    }

    .testimonials-row:nth-child(even) {
      direction: rtl;
    }

    .testimonials-row:nth-child(even) .testimonial-card {
      direction: ltr;
    }

    @keyframes scroll-left {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    @keyframes scroll-right {
      0% { transform: translateX(0); }
      100% { transform: translateX(50%); }
    }

    .testimonials-track {
      display: flex;
      gap: 24px;
      animation: scroll-left 40s linear infinite;
    }

    .testimonials-row:nth-child(even) .testimonials-track {
      animation: scroll-right 40s linear infinite;
    }

    .testimonial-card {
      flex-shrink: 0;
      width: 340px;
      background: var(--bg-white);
      border-radius: var(--radius-lg);
      border: 1px solid var(--border-subtle);
      padding: 28px;
    }

    .testimonial-text {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.7;
      margin-bottom: 20px;
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .testimonial-avatar {
      width: 40px;
      height: 40px;
      background: linear-gradient(135deg, var(--brand-primary) 0%, oklch(45% 0.22 265) 100%);
      border-radius: var(--radius-full);
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-size: 14px;
      font-weight: 600;
    }

    .testimonial-info h4 {
      font-size: 14px;
      font-weight: 600;
      color: var(--text-primary);
    }

    .testimonial-info p {
      font-size: 12px;
      color: var(--text-muted);
    }

    /* CTA Section */
    .cta {
      padding: 100px 0;
      background: var(--bg-white);
      text-align: center;
    }

    .cta-title {
      font-size: clamp(32px, 5vw, 48px);
      font-weight: 700;
      letter-spacing: -0.02em;
      color: var(--text-primary);
      margin-bottom: 16px;
    }

    .cta-desc {
      font-size: 16px;
      color: var(--text-secondary);
      max-width: 480px;
      margin: 0 auto 40px;
    }

    .cta-buttons {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 16px;
      margin-bottom: 80px;
      flex-wrap: wrap;
    }

    .app-icons-marquee {
      overflow: hidden;
      padding: 24px 0;
      position: relative;
    }

    .app-icons-marquee::before,
    .app-icons-marquee::after {
      content: '';
      position: absolute;
      top: 0;
      bottom: 0;
      width: 120px;
      z-index: 10;
      pointer-events: none;
    }

    .app-icons-marquee::before {
      left: 0;
      background: linear-gradient(to right, var(--bg-white), transparent);
    }

    .app-icons-marquee::after {
      right: 0;
      background: linear-gradient(to left, var(--bg-white), transparent);
    }

    .app-icons-track {
      display: flex;
      gap: 48px;
      align-items: center;
    }

    .app-icons-row {
      display: flex;
      gap: 48px;
      align-items: center;
    }

    .app-icon {
      width: 48px;
      height: 48px;
      background: var(--bg-surface);
      border-radius: var(--radius-md);
      border: 1px solid var(--border-subtle);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 20px;
      flex-shrink: 0;
    }

    @keyframes marquee-left {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    @keyframes marquee-right {
      0% { transform: translateX(0); }
      100% { transform: translateX(50%); }
    }

    .marquee-left {
      animation: marquee-left 30s linear infinite;
    }

    .marquee-right {
      animation: marquee-right 30s linear infinite;
    }

    /* Footer */
    .footer {
      padding: 64px 0 32px;
      background: var(--bg-surface);
      border-top: 1px solid var(--border-subtle);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 2fr repeat(3, 1fr);
      gap: 48px;
      margin-bottom: 48px;
    }

    .footer-brand p {
      font-size: 14px;
      color: var(--text-secondary);
      margin-top: 16px;
      max-width: 280px;
    }

    .footer-col h4 {
      font-size: 13px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      color: var(--text-primary);
      margin-bottom: 16px;
    }

    .footer-col a {
      display: block;
      font-size: 14px;
      color: var(--text-secondary);
      text-decoration: none;
      margin-bottom: 10px;
      transition: color var(--transition-fast);
    }

    .footer-col a:hover {
      color: var(--text-primary);
    }

    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding-top: 32px;
      border-top: 1px solid var(--border-subtle);
    }

    .footer-bottom p {
      font-size: 13px;
      color: var(--text-muted);
    }

    .footer-social {
      display: flex;
      gap: 16px;
    }

    .footer-social a {
      color: var(--text-muted);
      transition: color var(--transition-fast);
    }

    .footer-social a:hover {
      color: var(--text-primary);
    }

    /* Responsive */
    @media (max-width: 1024px) {
      .screenshots-grid {
        grid-template-columns: repeat(3, 1fr);
      }

      .tools-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .flows-content {
        grid-template-columns: 1fr;
      }

      .footer-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    @media (max-width: 768px) {
      .announcement-bar {
        font-size: 12px;
      }

      .nav-links {
        display: none;
      }

      .hero {
        padding: 60px 0 80px;
      }

      .hero-title {
        font-size: 36px;
      }

      .hero-subtitle {
        font-size: 16px;
      }

      .stats-grid {
        grid-template-columns: 1fr;
        gap: 16px;
      }

      .stat-card {
        padding: 24px;
      }

      .stat-number {
        font-size: 36px;
      }

      .screenshots-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 12px;
      }

      .tools-grid {
        grid-template-columns: 1fr;
      }

      .testimonial-card {
        width: 280px;
      }

      .footer-grid {
        grid-template-columns: 1fr;
        gap: 32px;
      }

      .footer-bottom {
        flex-direction: column;
        gap: 16px;
        text-align: center;
      }
    }

    @media (max-width: 480px) {
      .search-tabs {
        gap: 6px;
      }

      .search-tab {
        padding: 8px 14px;
        font-size: 13px;
      }

      .filter-pills {
        gap: 6px;
        justify-content: flex-start;
        flex-wrap: nowrap;
        overflow-x: auto;
        -webkit-overflow-scrolling: touch;
        padding-bottom: 8px;
      }

      .filter-pill {
        padding: 6px 12px;
        font-size: 12px;
      }

      .logo-row {
        gap: 24px;
      }

      .logo-row svg {
        height: 18px;
      }

      .screenshots-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }
  </style>
</head>
<body>
  <!-- Announcement Bar -->
  <div class="announcement-bar">
    2025 ScreenVault Awards — Celebrating the best on the internet.
  </div>

  <!-- Navigation -->
  <nav class="nav">
    <div class="nav-inner">
      <a href="/" class="nav-logo">
        <svg viewBox="0 0 28 28" fill="none">
          <rect width="28" height="28" rx="6" fill="currentColor"/>
          <rect x="6" y="6" width="16" height="16" rx="3" fill="var(--brand-primary)"/>
          <path d="M10 14h8M14 10v8" stroke="white" stroke-width="2" stroke-linecap="round"/>
        </svg>
        ScreenVault
      </a>
      <div class="nav-links">
        <a href="#">Pricing</a>
        <a href="#">Awards</a>
        <a href="#">Log in</a>
      </div>
      <div class="nav-cta">
        <a href="#" class="btn btn-primary">Join for free</a>
      </div>
    </div>
  </nav>

  <!-- Hero Section -->
  <section class="hero">
    <div class="container">
      <h1 class="hero-title">Discover real-world design inspiration.</h1>
      <p class="hero-subtitle">Featuring over 1,000 iOS & Web apps, and 200 sites — New content weekly.</p>
      <div class="hero-cta">
        <a href="#" class="btn btn-primary btn-lg">Join for free</a>
        <a href="#" class="btn btn-secondary btn-lg">See our plans</a>
      </div>
    </div>
  </section>

  <!-- Trusted By -->
  <section class="trusted-by">
    <div class="container">
      <p class="trusted-by-label">Trusted by design teams at</p>
      <div class="logo-row">
